import { createContext, useState, useEffect } from 'react';
import axios from 'axios';

export const AuthContext = createContext();

export const AuthContextProvider = ({ children }) => {
  const [currentUser, setCurrentUser] = useState(
    JSON.parse(sessionStorage.getItem('user')) || null
  );
  const [accessToken, setAccessToken] = useState(
    sessionStorage.getItem('accessToken') || null
  );
  const [refreshToken, setRefreshToken] = useState(
    sessionStorage.getItem('refreshToken') || null
  );
  const [error, setError] = useState(null);

  const login = async (username, password) => {
    console.log('AuthContext: Attempting login for:', username);
    try {
      // Clear old tokens
      sessionStorage.clear();
      console.log('AuthContext: Cleared sessionStorage');

      const res = await axios.post('http://localhost:5000/api/auth/login', {
        username,
        password,
      });

      console.log('AuthContext: Login response:', {
        user: res.data.user,
        accessToken: res.data.accessToken,
        refreshToken: res.data.refreshToken,
      });

      setCurrentUser(res.data.user);
      setAccessToken(res.data.accessToken);
      setRefreshToken(res.data.refreshToken);
      sessionStorage.setItem('user', JSON.stringify(res.data.user));
      sessionStorage.setItem('accessToken', res.data.accessToken);
      sessionStorage.setItem('refreshToken', res.data.refreshToken);
      setError(null);
      return true;
    } catch (err) {
      console.error('AuthContext: Login error:', err.message, err.response?.data);
      setError(err.response?.data?.message || 'Failed to login');
      return false;
    }
  };

  const logout = () => {
    console.log('AuthContext: Logging out');
    setCurrentUser(null);
    setAccessToken(null);
    setRefreshToken(null);
    setError(null);
    sessionStorage.clear();
  };

  const refreshAccessToken = async () => {
    console.log('AuthContext: Attempting to refresh access token');
    try {
      const res = await axios.post('http://localhost:5000/api/auth/refresh', {
        refreshToken,
      });
      console.log('AuthContext: Access token refreshed:', res.data.accessToken);
      setAccessToken(res.data.accessToken);
      sessionStorage.setItem('accessToken', res.data.accessToken);
      setError(null);
      return res.data.accessToken;
    } catch (err) {
      console.error('AuthContext: Error refreshing token:', err.message, err.response?.data);
      setError('Session expired. Please login again.');
      logout();
      throw err;
    }
  };

  useEffect(() => {
    console.log('AuthContext: Current user:', currentUser?.username);
    console.log('AuthContext: Access token:', accessToken ? accessToken : 'None');
    console.log('AuthContext: Refresh token:', refreshToken ? refreshToken : 'None');
  }, [currentUser, accessToken, refreshToken]);

  return (
    <AuthContext.Provider
      value={{ currentUser, accessToken, login, logout, refreshAccessToken, error }}
    >
      {children}
    </AuthContext.Provider>
  );
};
